//! Real MCP dispatch -> Core -> shaped VNDB response; the proposal never creates a binding.
use serde_json::json;
use galroon_mcp::{client::Core,tools::Tools};
use tokio::io::{AsyncReadExt,AsyncWriteExt};
#[tokio::test]async fn suggest_match_creates_a_proposal_without_work_or_binding(){
 let provider=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let provider_url=format!("http://{}",provider.local_addr().unwrap());std::env::set_var("GALROON_VNDB_API",&provider_url);
 let mock=tokio::spawn(async move{loop{let(mut socket,_)=provider.accept().await.unwrap();let mut bytes=Vec::new();let mut chunk=[0;4096];loop{let n=socket.read(&mut chunk).await.unwrap();if n==0{break;}bytes.extend_from_slice(&chunk[..n]);if let Some(end)=bytes.windows(4).position(|w|w==b"\r\n\r\n"){let header=String::from_utf8_lossy(&bytes[..end]);let length:usize=header.lines().find_map(|line|line.to_ascii_lowercase().strip_prefix("content-length:").map(|s|s.trim().parse().unwrap())).unwrap();if bytes.len()>=end+4+length{let body:serde_json::Value=serde_json::from_slice(&bytes[end+4..end+4+length]).unwrap();// Only the exact work lookup is answered; anything else (a background search) gets no results.
let hit=body["filters"]==json!(["id","=","v910003"]);bytes=if hit{b"hit".to_vec()}else{Vec::new()};break;}}}let body=if bytes==b"hit"{json!({"results":[{"id":"v910003","title":"Story","alttitle":"物語","aliases":["故事"]}]})}else{json!({"results":[],"more":false})}.to_string();socket.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).as_bytes()).await.unwrap();}});
 let dir=tempfile::tempdir().unwrap();let app=galroon_core::initialize(dir.path().join("state")).unwrap();let db=app.db.clone();{let c=db.lock().unwrap();c.execute_batch("INSERT INTO roots(id,path,label) VALUES('root','generated','Source');INSERT INTO resources(id,root_id,relative_path,title,kind) VALUES('r','root','Unknown','Unknown','directory');INSERT INTO files(id,root_id,path,relative_path,size,mtime,ext,seen_job) VALUES('f','root','Unknown/data.bin','Unknown/data.bin',1,'1','bin','');INSERT INTO resource_files VALUES('r','f');INSERT INTO settings(key,value) VALUES('auto_match_enabled','0') ON CONFLICT(key) DO UPDATE SET value='0';").unwrap();}
 let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let url=format!("http://{}",listener.local_addr().unwrap());let client=Core::new(url,app.token.clone(),None).unwrap();let server=tokio::spawn(galroon_core::serve_listener(app,listener));let tools=Tools::fixed(client);
 let definition=galroon_mcp::tools::definitions().into_iter().find(|t|t["name"]=="suggest_match").unwrap();assert_eq!(definition["annotations"]["readOnlyHint"],false);assert_eq!(definition["annotations"]["destructiveHint"],false);
 let result=tools.call("suggest_match",&json!({"resource_id":"r","revision":1,"vndb_ids":["v910003"],"query":"故事","rationale":"Exact Chinese alias"})).await.unwrap();assert_eq!(result["state"],"open");assert_eq!(result["verified"],true);
 let c=db.lock().unwrap();assert_eq!(c.query_row("SELECT count(*) FROM match_suggestions WHERE state='open'",[],|r|r.get::<_,i64>(0)).unwrap(),1);for table in ["works","resource_bindings","resource_history"]{assert_eq!(c.query_row(&format!("SELECT count(*) FROM {table}"),[],|r|r.get::<_,i64>(0)).unwrap(),0);}assert_eq!(c.query_row("SELECT work_id IS NULL AND revision=1 FROM resources WHERE id='r'",[],|r|r.get::<_,bool>(0)).unwrap(),true);drop(c);server.abort();mock.abort();std::env::remove_var("GALROON_VNDB_API");
}
